INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Lessons Learned ohne Dokumentation nützlich?', 2, '[{"text": "Nein", "correct": true, "because": "Ohne Aufzeichnung verloren"}, {"text": "Ja", "correct": false, "because": "Fehlende Weitergabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Lessons Learned?', 3, '[{"text": "Verbesserung", "correct": true, "because": "Zukünftige Projekte optimieren"}, {"text": "Marketing", "correct": false, "because": "Anderer Fokus"}, {"text": "Performance", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu Lessons Learned?', 5, '[{"text": "Probleme", "correct": true, "because": "Zeigt Herausforderungen"}, {"text": "Lösungen", "correct": true, "because": "Bietet Ansätze"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}, {"text": "Hardware-Specs", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Lessons Learned brauchen Beispiele. b) Sie sind nur für große Projekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) auch für kleine Projekte"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Lessons Learned?', 4, '[{"text": "Erkenntnisse", "correct": false, "because": "Kern der Dokumentation"}, {"text": "Lösungsvorschläge", "correct": false, "because": "Hilft zukünftig"}, {"text": "Schriftart", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Lessons Learned nur am Projektende gesammelt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Laufend möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Format wähle ich für Lessons Learned?', 3, '[{"text": "Bericht", "correct": true, "because": "Strukturiert und zugänglich"}, {"text": "E-Mail", "correct": false, "because": "Unstrukturiert"}, {"text": "Notizen", "correct": false, "because": "Wenig organisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen Lessons Learned effektiv?', 5, '[{"text": "Klarheit", "correct": true, "because": "Fördert Verständnis"}, {"text": "Praxisbezug", "correct": true, "because": "Relevanz zeigen"}, {"text": "Hohe Auflösung", "correct": false, "because": "Irrelevant"}, {"text": "Lange Texte", "correct": false, "because": "Ermüdend"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Lessons Learned sind nur für Fehler. b) Erfolge werden ignoriert. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "Auch Erfolge relevant"}, {"text": "Beides stimmt", "correct": false, "because": "Nicht exklusiv"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Lessons Learned?', 4, '[{"text": "Problembeschreibung", "correct": false, "because": "Gibt Kontext"}, {"text": "Lösungsansatz", "correct": false, "because": "Bietet Nutzen"}, {"text": "Teamfotos", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Lessons Learned nur für das Team?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für andere Projekte"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Inhalte sind in Lessons Learned entscheidend?', 4, '[{"text": "Herausforderungen", "correct": true, "because": "Zeigt Schwierigkeiten"}, {"text": "Empfehlungen", "correct": true, "because": "Verbessert Zukunft"}, {"text": "UI-Design", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Lessons Learned nur einmal gesammelt werden. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Laufend nützlich"}, {"text": "Ja", "correct": false, "because": "Dynamisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Lessons Learned?', 3, '[{"text": "Relevanz", "correct": true, "because": "Nutzen maximieren"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Qualität zählt"}, {"text": "Technische Tiefe", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Lessons Learned brauchen Struktur. b) Chaos ist akzeptabel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Chaos verwirrt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das Sammeln von Lessons Learned?', 5, '[{"text": "Wissensweitergabe", "correct": true, "because": "Team profitiert"}, {"text": "Fehlervermeidung", "correct": true, "because": "Lernt aus Vergangenheit"}, {"text": "Hohe Kosten", "correct": false, "because": "Kein Vorteil"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Lessons Learned unwichtig?', 3, '[{"text": "Erfahrungen", "correct": false, "because": "Kern der Dokumentation"}, {"text": "Vorschläge", "correct": false, "because": "Verbessert Prozesse"}, {"text": "Monitorgröße", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzen Lessons Learned die Planung?', 3, '[{"text": "Nein", "correct": true, "because": "Ergänzen sie"}, {"text": "Ja", "correct": false, "because": "Planung bleibt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Lessons Learned nur negativ sind?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Erfolge enthalten"}, {"text": "Ja", "correct": false, "because": "Nicht exklusiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für Lessons Learned entscheidend?', 4, '[{"text": "Praxisnähe", "correct": true, "because": "Relevanz sichern"}, {"text": "Hohe Komplexität", "correct": false, "because": "Verwirrt"}, {"text": "Statische Daten", "correct": false, "because": "Nicht primär"}]');
